using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Reflection;
using System.Collections.Generic;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Controls.Primitives;
using System.Windows.Markup;
using System.Windows.Input;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using System.Windows.Threading;
using PeerChatDesktop;
class EmojiFeatureTest {
    static void Check(bool value,string reason){if(!value)throw new Exception(reason);}
    static readonly string[] Corpus={"😀","👩🏽‍💻","👨‍👩‍👧‍👦","🇺🇸","🇨🇦","1️⃣","❤️","🏳️‍🌈","🏴\U000E0067\U000E0062\U000E0065\U000E006E\U000E0067\U000E007F","e\u0301"};
    static object Field(object o,string name){return o.GetType().GetField(name,BindingFlags.NonPublic|BindingFlags.Instance).GetValue(o);}
    static void SaveImage(FrameworkElement element,string path){var bmp=new RenderTargetBitmap((int)element.ActualWidth,(int)element.ActualHeight,96,96,PixelFormats.Pbgra32);bmp.Render(element);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(bmp));using(var file=File.Create(path))png.Save(file);}
    [STAThread] static int Main(string[] args){try{var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};string root=Path.Combine(args[0],Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);
        foreach(string s in Corpus){Check(EmojiEditing.Boundaries(s).SequenceEqual(new[]{0,s.Length}),"split sequence");Check(new UTF8Encoding(false,true).GetString(new UTF8Encoding(false,true).GetBytes(s))==s,"UTF8 round trip");var box=new TextBox{Text="a"+s+"b"};var editHost=new Window{Content=box,Width=300,Height=100,ShowInTaskbar=false};editHost.Show();editHost.UpdateLayout();box.Focus();box.IsUndoEnabled=false;box.IsUndoEnabled=true;box.Select(1+s.Length,0);Check(EmojiComposer.Delete(box,true)&&box.Text=="ab","backspace whole cluster");box.Undo();Check(box.Text=="a"+s+"b","undo cluster delete");EmojiComposer.Insert(box,"👍",2,1);Check(box.Text=="a👍b","selected interior expands safely");box.Undo();Check(box.Text=="a"+s+"b","undo insertion");editHost.Close();}
        Check(EmojiEditing.Boundaries("🇺🇸🇨🇦🇯🇵").Length==4,"flag pairing");
        Check(EmojiCatalog.Search("programmer","People").Count()==2&&EmojiCatalog.Search("LOL",null).Count()==2&&EmojiCatalog.Search("nonexistent123",null).Count()==0,"search/category");
        foreach(var e in EmojiCatalog.All)foreach(int t in Enumerable.Range(0,e.SkinTone?6:1))Check(EmojiEditing.Boundaries(e.Variant(t)).Length==2,"catalog variant cluster");
        Check(EmojiCatalog.All.First(e=>e.Text=="✌️").Variant(1)=="✌🏻","BMP tone standard sequence");
        var usage=new EmojiUsage(root,"fixture");usage.Used("👩🏽‍💻");usage.Used("😀");usage.Used("👩🏽‍💻");var reopened=new EmojiUsage(root,"fixture");Check(reopened.Recent[0]=="👩🏽‍💻"&&reopened.Counts["👩🏽‍💻"]==2,"protected persistence/frequency");Check(new EmojiUsage(root,"other-profile").Recent.Count==0,"profile binding");Check(!Encoding.UTF8.GetString(File.ReadAllBytes(Path.Combine(root,"emoji-usage.v1"))).Contains("👩🏽‍💻"),"preferences plaintext");
        Window window;using(var stream=typeof(CoreAdapter).Assembly.GetManifestResourceStream("Main.xaml"))window=(Window)XamlReader.Load(stream);window.Show();var composer=(TextBox)window.FindName("Composer");composer.IsEnabled=true;composer.Text="";window.UpdateLayout();double empty=composer.ActualHeight;Console.WriteLine("COMPOSER empty="+empty+" min="+composer.MinHeight+" padding="+composer.Padding);Check(empty<=50&&empty>=42,"compact empty composer");composer.Text="a\nb\nc\nd\ne";window.UpdateLayout();Check(composer.ActualHeight>empty&&composer.ActualHeight<=150,"bounded multiline growth");Check(((TextBlock)window.FindName("ComposerHint")).VerticalAlignment==VerticalAlignment.Center&&composer.VerticalContentAlignment==VerticalAlignment.Center,"caret/placeholder alignment");
        var picker=new EmojiPicker(window,reopened);picker.Dispatcher.BeginInvoke(DispatcherPriority.ApplicationIdle,new Action(()=>{var search=(TextBox)Field(picker,"search");search.Text="programmer";picker.RaiseEvent(new KeyEventArgs(Keyboard.PrimaryDevice,PresentationSource.FromVisual(picker),0,Key.Down){RoutedEvent=Keyboard.PreviewKeyDownEvent});Check(((UniformGrid)Field(picker,"grid")).Children[0].IsKeyboardFocusWithin,"keyboard search to results");Check(((UniformGrid)Field(picker,"grid")).Children.Count==2,"live search");((ComboBox)Field(picker,"tone")).SelectedIndex=3;var grid=(UniformGrid)Field(picker,"grid");Check(((string)((Button)grid.Children[0]).Content).Contains("🏽"),"skin tone selection");picker.UpdateLayout();var bmp=new RenderTargetBitmap((int)picker.ActualWidth,(int)picker.ActualHeight,96,96,PixelFormats.Pbgra32);bmp.Render(picker);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(bmp));using(var file=File.Create(Path.Combine(root,"emoji-picker.png")))png.Save(file);((Button)grid.Children[0]).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));}));Check(picker.ShowDialog()==true&&picker.Selection.Contains("🏽"),"picker select");
        composer.Text="hello world";composer.IsUndoEnabled=false;composer.IsUndoEnabled=true;composer.Select(6,5);EmojiComposer.Insert(composer,"😀",6,5);Check(composer.Text=="hello 😀"&&composer.CaretIndex==8,"ordinary selection caret insertion");composer.Undo();Check(composer.Text=="hello world","ordinary selection undo");composer.Redo();Check(composer.Text=="hello 😀","emoji redo");composer.Select(6,0);Check(EmojiComposer.Delete(composer,false)&&composer.Text=="hello ","forward delete emoji");
        var cancelled=new EmojiPicker(window,reopened);cancelled.Dispatcher.BeginInvoke(DispatcherPriority.ApplicationIdle,new Action(()=>{Check(((TextBox)Field(cancelled,"search")).IsKeyboardFocusWithin,"search initial keyboard focus");cancelled.RaiseEvent(new KeyEventArgs(Keyboard.PrimaryDevice,PresentationSource.FromVisual(cancelled),0,Key.Escape){RoutedEvent=Keyboard.PreviewKeyDownEvent});}));Check(cancelled.ShowDialog()!=true&&cancelled.Selection==null,"cancel no selection");
        var overview=new EmojiPicker(window,reopened);overview.Dispatcher.BeginInvoke(DispatcherPriority.ApplicationIdle,new Action(()=>{overview.UpdateLayout();SaveImage(overview,Path.Combine(root,"emoji-overview.png"));var categories=(ComboBox)Field(overview,"category");categories.SelectedItem="Recent";Check(((UniformGrid)Field(overview,"grid")).Children.Count==2,"recent picker");categories.SelectedItem="Frequent";Check((string)((Button)((UniformGrid)Field(overview,"grid")).Children[0]).Content=="👩🏽‍💻","frequent ordering");overview.Close();}));overview.ShowDialog();
        composer.Text="";((TextBlock)window.FindName("ComposerHint")).Visibility=Visibility.Visible;window.UpdateLayout();SaveImage(window,Path.Combine(root,"composer.png"));
        var boundedUsage=new EmojiUsage(Path.Combine(root,"bounded"),"fixture");foreach(var entry in EmojiCatalog.All.Take(30))boundedUsage.Used(entry.Text);Check(new EmojiUsage(Path.Combine(root,"bounded"),"fixture").Recent.Count==24,"bounded recent restart");File.WriteAllBytes(Path.Combine(root,"bounded","emoji-usage.v1"),new byte[]{1,2,3});Check(new EmojiUsage(Path.Combine(root,"bounded"),"fixture").Recent.Count==0,"corrupt optional preferences isolated");
        var chat=new ChatText{Message=String.Join("\n",Corpus)};Check(chat.Message==String.Join("\n",Corpus),"chat exact text");var viewer=new BoundedTextView(String.Concat(Enumerable.Repeat(String.Join("\n",Corpus),80)),false,"Long message");Check(viewer.Viewer.Text.Contains("👩🏽‍💻")&&viewer.Viewer.IsReadOnly,"long preview exact");window.Close();Console.WriteLine("PASS: picker search/category/tone/select, native rendering smoke, compact growth/alignment, Unicode clusters/edit/undo, protected usage/restart/profile isolation and long viewer. Physical glyph quality pending.");return 0;
    }catch(Exception e){Console.Error.WriteLine(e.ToString());return 1;}}
}
